import { CurrencyPipe } from '@angular/common';
import { ChangeDetectionStrategy, Component, computed, inject, signal } from '@angular/core';
import { createWhatsappUrl } from '../shared/contact';
import { ProductCatalogService } from './product-catalog.service';
import { Product, ProductCategory } from './product.model';

const normalize = (value: string): string => value.normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase();

@Component({
  selector: 'app-products',
  imports: [CurrencyPipe],
  templateUrl: './products.component.html',
  styleUrl: './products.component.scss',
  changeDetection: ChangeDetectionStrategy.OnPush,
})
export class ProductsComponent {
  private readonly catalog = inject(ProductCatalogService);
  protected readonly search = signal('');
  protected readonly category = signal<ProductCategory | 'Todos'>('Todos');
  protected readonly categories = computed(() => ['Todos' as const, ...new Set(this.catalog.products.map(product => product.category))]);
  protected readonly products = computed(() => {
    const query = normalize(this.search().trim());
    return this.catalog.products.filter(product =>
      (this.category() === 'Todos' || product.category === this.category()) &&
      normalize(`${product.name} ${product.category} ${product.description}`).includes(query),
    );
  });

  protected consultUrl(product: Product): string {
    return createWhatsappUrl(`Hola ModoConectado, quiero consultar por ${product.name} (ref. ${product.id}). ¿Me cuentan el precio, las características y la disponibilidad?`);
  }

  protected resetFilters(): void {
    this.search.set('');
    this.category.set('Todos');
  }
}
<main class="catalog">
  <section class="catalog-intro" aria-labelledby="catalog-title">
    <span class="eyebrow">TECNOLOGÍA PARA TU DÍA A DÍA</span>
    <h1 id="catalog-title">Conectá tu mundo.</h1>
    <p>Explorá nuestros productos y encontrá la tecnología que va con vos.</p>
  </section>

  <section aria-label="Catálogo de productos">
    <div class="catalog-toolbar">
      <div><h2>Productos</h2><p>Descubrí nuevas posibilidades para tus espacios.</p></div>
      <label class="search"><span>Buscar productos</span><input type="search" placeholder="Buscar por nombre o categoría…" [value]="search()" (input)="search.set($any($event.target).value)"></label>
    </div>
    <div class="categories" aria-label="Filtrar por categoría">
      @for (item of categories(); track item) {
        <button type="button" [class.selected]="category() === item" [attr.aria-pressed]="category() === item" (click)="category.set(item)">{{ item }}</button>
      }
    </div>
    <p class="results" role="status">{{ products().length }} {{ products().length === 1 ? 'producto' : 'productos' }}</p>
    <div class="product-grid">
      @for (product of products(); track product.id) {
        <article class="product-card">
          <div class="product-image"><img [src]="product.image" [alt]="product.name" loading="lazy" width="320" height="260"><span>{{ product.category }}</span></div>
          <div class="product-content">
            <h3>{{ product.name }}</h3><p>{{ product.description }}</p>
            <ul>@for (feature of product.features; track feature) { <li>{{ feature }}</li> }</ul>
            <div class="product-bottom">
              @if (product.price !== null) { <strong>{{ product.price | currency:'ARS':'$':'1.0-0':'es-AR' }}</strong> } @else { <strong>Consultar precio</strong> }
              <a [href]="consultUrl(product)" target="_blank" rel="noopener noreferrer" [attr.aria-label]="'Consultar por ' + product.name + ' en WhatsApp'">Consultar <span aria-hidden="true">↗</span></a>
            </div>
          </div>
        </article>
      } @empty {
        <div class="empty-state"><h3>No encontramos productos</h3><p>Probá con otro nombre o seleccioná otra categoría.</p><button type="button" (click)="resetFilters()">Ver todos los productos</button></div>
      }
    </div>
  </section>
  <footer>ModoConectado · Tecnología y soluciones para tus espacios</footer>

</main>
